✓ Accessible
RovingTabindex.tsx
Copy
import { useState, useRef, useEffect } from 'react';

function Toolbar() {
const [activeIndex, setActiveIndex] = useState(0);
const items = ['Bold', 'Italic', 'Underline', 'Link'];
const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);

// Move DOM focus whenever activeIndex changes
useEffect(() => {

buttonRefs.current[activeIndex]?.focus();
}, [activeIndex]);

const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
switch (e.key) {
case 'ArrowRight':
e.preventDefault();
setActiveIndex((index + 1) % items.length);
break;
case 'ArrowLeft':
e.preventDefault();
setActiveIndex((index - 1 + items.length) % items.length);
break;
case 'Home':
e.preventDefault();
setActiveIndex(0);
break;
case 'End':
e.preventDefault();
setActiveIndex(items.length - 1);
break;
}
};

return (
<div role="toolbar" aria-label="Formatting options">
{items.map((item, i) => (
<button
key={item}
ref={(el) => { buttonRefs.current[i] = el; }}
tabIndex={i === activeIndex ? 0 : -1}
onKeyDown={(e) => handleKeyDown(e, i)}
onClick={() => setActiveIndex(i)}
aria-pressed={i === activeIndex}
>
{item}
</button>
))}
</div>
);
}

