// GOOD: Only prevent default for the keys you handle
element.addEventListener('keydown', (e) => {
if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
e.preventDefault();
handleArrowNavigation(e.key);
}
// Tab, Shift+Tab, Escape pass through naturally
});

// GOOD: Validate on blur without trapping
input.addEventListener('blur', () => {
validateField(input); // Validate but do NOT refocus
});

Focus moves into the modal when it opens (to the modal container or first focusable element).
Tab cycles within the modal only. From the last element, Tab wraps to the first. From the first, Shift+Tab wraps to the last.
Escape closes the modal. This is the standard convention users expect.
Focus returns to the trigger when the modal closes, so the user resumes where they left off.
Background content is inert. Use aria-modal="true" and role="dialog".

Interactive Demo

Click 'Open Dialog' to open the modal. Try Tab (cycles within), Shift+Tab (wraps backward), and Escape (closes and returns focus to the button).
Open DialogFocus is trapped inside the dialog. Escape closes it. Focus returns to this button on close.

✓ Accessible
AccessibleModal.tsx
Copy
import { useRef, useEffect } from 'react';

interface ModalProps {
isOpen: boolean;
onClose: () => void;
children: React.ReactNode;
}

function Modal({ isOpen, onClose, children }: ModalProps) {
const modalRef = useRef<HTMLDivElement>(null);
const previousFocusRef = useRef<Element | null>(null);

useEffect(() => {
if (isOpen) {
// 1. Store the currently focused element
previousFocusRef.current = document.activeElement;
// 2. Move focus into the modal
modalRef.current?.focus();
} else if (previousFocusRef.current) {
// 4. Return focus to the trigger on close
(previousFocusRef.current as HTMLElement)?.focus();

previousFocusRef.current = null;
}
}, [isOpen]);

const handleKeyDown = (e: React.KeyboardEvent) => {
// 3. Escape closes the modal
if (e.key === 'Escape') {
onClose();
return;
}

// 2. Trap Tab within the modal
if (e.key === 'Tab') {
const focusable = modalRef.current?.querySelectorAll(
'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
);
if (!focusable?.length) return;

const first = focusable[0] as HTMLElement;
const last = focusable[focusable.length - 1] as HTMLElement;

if (e.shiftKey && document.activeElement === first) {
e.preventDefault();
last.focus(); // Wrap backward
} else if (!e.shiftKey && document.activeElement === last) {
e.preventDefault();
first.focus(); // Wrap forward
}
}
};

if (!isOpen) return null;

return (
<>
<div className="backdrop" onClick={onClose} aria-hidden="true" />
<div
role="dialog"
aria-modal="true"
aria-label="Modal title"
ref={modalRef}
tabIndex={-1}
onKeyDown={handleKeyDown}
>
{children}
</div>
</>
);
}

The single most common mobile accessibility failure is a target too small to hit. Two standards apply, and they answer different questions:
WCAG 2.5.8 Target Size (Minimum), AA — the legal floor: 24×24 CSS pixels, with exceptions for targets that have enough spacing around them, inline links inside a sentence, and cases where the size is essential.
Platform guidance — the size to actually build to: 44×44 pt (Apple Human Interface Guidelines) and 48×48 dp (Google Material Design).

Treat 24px as the number you must never drop below and 44pt / 48dp as your ergonomic target. Crucially, the tappable area is what counts, not the visible glyph: you can keep a 16px icon and still meet the target by extending the hit region with padding.
/* Mobile web: small icon, real hit area */
.icon-button {
min-width: 44px;
min-height: 44px;
display: inline-flex;
align-items: center;
justify-content: center;
}

On Android, wrap a small control in a TouchDelegate or set android:minWidth/minHeight to 48dp. In SwiftUI, standard controls already claim a minimum hit region; for custom shapes add .contentShape(Rectangle()) and adequate padding. When two targets sit close together, the spacing exception in 2.5.8 only helps if the gap keeps their 24px hit circles from overlapping — crowded toolbars are the usual offender.

// An icon-only button with no visible text
let favoriteButton = UIButton(type: .system)
favoriteButton.setImage(UIImage(named: "heart"), for: .normal)

// VoiceOver needs a name, a role, and (optionally) a hint:
favoriteButton.isAccessibilityElement = true
favoriteButton.accessibilityLabel = "Favorite" // name
favoriteButton.accessibilityTraits = .button // role
favoriteButton.accessibilityHint = "Adds this article to your favorites"

// Announce an async change VoiceOver would otherwise miss:
UIAccessibility.post(notification: .announcement,
argument: "Added to favorites")

// Decorative image: take it out of the accessibility tree
decorImageView.isAccessibilityElement = false

// Text must respect the user's Dynamic Type setting:
titleLabel.font = UIFont.preferredFont(forTextStyle: .headline)
titleLabel.adjustsFontForContentSizeCategory = true

SwiftUI generates accessibility from your view tree, so most controls are labeled for free. You add modifiers to name icon-only controls, group related views into a single swipe stop, and hide decoration. System text styles scale with Dynamic Type automatically.
Button(action: toggleFavorite) {
Image(systemName: "heart") // decorative glyph inside the button
}
.accessibilityLabel("Favorite") // name; the .isButton trait is automatic
.accessibilityHint("Adds this article to your favorites")

// Collapse a rating row into ONE element with a combined label:
HStack {
Image(systemName: "star.fill")
Text("4.8")
Text("(120 reviews)")
}
.accessibilityElement(children: .combine) // reads "star, 4.8, 120 reviews" as one stop

// Hide a purely decorative image:
Image("hero-pattern").accessibilityHidden(true)

// System text styles scale with Dynamic Type automatically:
Text("Order summary").font(.headline)

Add a role trait when a custom view acts like a control: .accessibilityAddTraits(.isButton), .isHeader, or .isSelected. For values that change, keep accessibilityValue in sync so a slider announces “50 percent,” not just its label. When you scale custom dimensions with the font size, use @ScaledMetric so padding and icons grow alongside the text.

// Icon-only button: label it; Material enforces a 48dp touch target
IconButton(onClick = ::toggleFavorite) {
Icon(
imageVector = Icons.Default.Favorite,
contentDescription = "Favorite" // null would mark it decorative
)
}

// Merge a rating row into one node with a combined description:
Row(
modifier = Modifier.semantics(mergeDescendants = true) {}
) {
Icon(Icons.Default.Star, contentDescription = null)
Text("4.8")
Text("(120 reviews)")
}

// A live region announces its own updates, no manual event needed:
Text(
text = statusMessage,
modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite }
)

// Text in sp scales with the OS font-size setting:
Text("Order summary", fontSize = 16.sp)

Expose role and state through the semantics block — role = Role.Button, stateDescription, selected, toggleableState — and use Modifier.clearAndSetSemantics when you need to replace a subtree's auto-generated description with a single clean one. TalkBack, like VoiceOver, moves focus by swipe, so reading order follows the semantics tree; check it matches the visual order.

On mobile web the accessibility tree is built for you: write semantic HTML — real <button> and <a href>, labeled inputs, headings, and ARIA only where HTML falls short — and Safari with VoiceOver or Chrome with TalkBack turns it into something a screen reader can navigate. Everything in our keyboard accessibility and accessible forms guides applies. The mobile-web-specific work is smaller and concentrated:
The viewport tag is the number-one mobile-web bug. Disabling zoom to stop your layout from “breaking” is an accessibility failure — low-vision users rely on pinch-zoom.
<!-- Correct: users can pinch-zoom -->
<meta name="viewport" content="width=device-width, initial-scale=1" />

<!-- Wrong: blocks zoom, fails WCAG 1.4.4 -->
<meta name="viewport"
content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no" />

Beyond the viewport: give touch targets a real CSS hit area (section 1); make layouts reflow at 320px so nothing needs horizontal scrolling; and show focus with :focus-visible so keyboard and switch users get a clear indicator without it flashing on every tap.
.icon-button:focus-visible {
outline: 3px solid #2563eb;
outline-offset: 2px;
}

When a client-side route changes, the browser does not reset focus the way a full page load would. Keyboard and screen reader users are left on whatever link they clicked, now pointing at content that no longer exists. Move focus to the top of the new view — usually its heading.
// A route-aware heading that receives focus after navigation
import { useEffect, useRef } from "react"
import { usePathname } from "next/navigation"

export function PageHeading({ children }) {
const ref = useRef(null)
const pathname = usePathname()

useEffect(() => {
ref.current?.focus()
}, [pathname])

return (
<h1 ref={ref} tabIndex={-1} className="outline-none">
{children}
</h1>
)
}
tabIndex={-1} lets the heading receive programmatic focus without adding it to the Tab order. Next.js App Router also ships a built-in route announcer that reads the new document <title> on navigation, so keeping page titles unique and descriptive is part of the same job. This satisfies 2.4.3 Focus Order. Provide a skip link to #main as well.

A dialog is the classic React focus challenge. When it opens, focus must move into it; while open, focus must stay trapped inside; on close, focus must return to the control that opened it. The native <dialog> element handles most of this, and its showModal() method traps focus and supports Escape for you.
import { useEffect, useRef } from "react"

export function ConfirmDialog({ open, onClose, children }) {
const dialogRef = useRef(null)

useEffect(() => {
const node = dialogRef.current
if (!node) return
if (open) node.showModal() // traps focus + enables Escape
else node.close()
}, [open])

return (
<dialog
ref={dialogRef}
aria-labelledby="dialog-title"
onClose={onClose}
className="rounded-lg p-6 backdrop:bg-black/50"
>
<h2 id="dialog-title">Delete this project?</h2>
{children}
<button type="button" onClick={onClose}>Cancel</button>
</dialog>
)
}
If you build a custom overlay instead of using <dialog>, you must add role="dialog", aria-modal="true", an accessible name via aria-labelledby, a focus trap, Escape-to-close, and focus restoration yourself — which is exactly why headless libraries like Radix UI, React Aria, and Headless UI exist. See the accessible modal pattern for the full interaction spec.

React updates the DOM silently. When search results load, a toast appears, or a form saves, a sighted user sees it instantly — a screen reader user hears nothing unless the change happens inside an aria-live region. Render a persistent live region and update its text.
function SearchResults({ status, results }) {
return (
<div>
{/* Polite: announced when the user is idle, never interrupts */}
<p aria-live="polite" className="sr-only">
{status === "loading"
? "Searching…"
: results.length + " results found"}
</p>

<ul>
{results.map((r) => (
<li key={r.id}>{r.title}</li>
))}
</ul>
</div>
)
}
Use aria-live="polite" for status updates and aria-live="assertive" only for urgent, interrupting messages like a session-timeout warning. The region must exist in the DOM before its text changes, so render it empty rather than mounting it on demand. This satisfies 4.1.3 Status Messages.

In a reusable input component you cannot hardcode an id — render it twice and the ids collide, breaking every label and error association. React's useId hook generates a stable, hydration-safe id. Derive the field and error ids from it and wire them with htmlFor, aria-describedby, and aria-invalid.
import { useId } from "react"

export function TextField({ label, error, ...props }) {
const id = useId()
const errorId = id + "-error"

return (
<div>
<label htmlFor={id}>{label}</label>
<input
id={id}
aria-invalid={error ? true : undefined}
aria-describedby={error ? errorId : undefined}
{...props}
/>
{error && (
<p id={errorId} className="text-red-600">
{error}
</p>
)}
</div>
)
}
Note the JSX specifics: use htmlFor (not for) and className (not class), but keep aria-* attributes hyphenated. Only set aria-invalid and aria-describedby when there is actually an error, so assistive tech is not told about a message that is not shown. For the full treatment of labels, grouping, validation, and error summaries, see the accessible forms guide.

When you genuinely need a custom widget — a disclosure, a tab set, a combobox — ARIA describes its state to assistive technology. Follow the ARIA Authoring Practices patterns exactly, and mirror the ARIA state in your React state.
function Disclosure({ label, children }) {
const [open, setOpen] = useState(false)
const panelId = useId()

return (
<>
<button
type="button"
aria-expanded={open}
aria-controls={panelId}
onClick={() => setOpen((v) => !v)}
>
{label}
</button>
<div id={panelId} hidden={!open}>
{children}
</div>
</>
)
}
Because the toggle is a real <button>, keyboard support and focus come free — you only add aria-expanded and aria-controls to describe the relationship. For widgets that need arrow-key navigation (tabs, menus, listboxes), implement a roving tabIndex and the documented key bindings. Our ARIA roles & attributes reference lists the exact roles and states for each pattern.

Automated checks catch a meaningful share of issues and stop regressions — but they find roughly a third to a half of WCAG problems, so they supplement rather than replace manual testing. Layer three tools into your workflow:
// 1. Lint as you type — jsx-a11y ships with Next.js's ESLint config
// Flags <img> without alt, onClick on non-interactive elements, etc.

// 2. Component tests: React Testing Library + jest-axe
import { render } from "@testing-library/react"
import { axe } from "jest-axe"

test("TextField has no axe violations", async () => {
const { container } = render(
<TextField label="Email" error="Enter a valid email" />
)
expect(await axe(container)).toHaveNoViolations()
})

// 3. End-to-end: axe-core in Playwright against real pages
import AxeBuilder from "@axe-core/playwright"

test("home page is accessible", async ({ page }) => {
await page.goto("/")
const results = await new AxeBuilder({ page }).analyze()
expect(results.violations).toEqual([])
})
React Testing Library nudges you toward accessible queries — getByRole and getByLabelText only pass when the accessibility tree is correct, so writing tests this way surfaces missing names early. Finish every feature with a manual keyboard pass and a screen reader pass. Read our comparison of automated vs manual testing to see where each fits.

The standard visual treatment keeps the skip link off-screen until it is focused, then slides it into view at the top of the page. The critical rule is that the hiding technique must keep the link in the tab order. display: none and visibility: hidden both remove an element from the tab order, so a link hidden that way can never be reached and the skip mechanism silently does nothing. Position it off-screen instead:
.skip-link {
position: absolute;
left: 0;
top: 0;
/* Move it off-screen without removing it from the tab order */
transform: translateY(-120%);
padding: 0.75rem 1rem;
background: #1d4ed8;
color: #fff;
border-radius: 0 0 0.375rem 0;
z-index: 1000;
transition: transform 0.15s ease-in-out;
}

/* Bring it into view when a keyboard user tabs onto it */
.skip-link:focus {
transform: translateY(0);
/* A visible focus indicator satisfies 2.4.7 */
outline: 3px solid #fff;
outline-offset: 2px;
}

A transform keeps the element rendered and focusable while pushing it out of sight, so it stays in the tab order and animates back on focus. The older clip or off-screen left: -9999px techniques work too, as long as you restore the link to a visible on-screen position on :focus. Whichever you choose, the :focus state must place a clearly visible link in a predictable spot, usually the top-left corner, with an obvious focus indicator.

If your header is position: sticky or fixed, the target can end up scrolled to the very top of the viewport and then covered by that header, so focus has moved but the user cannot see where. That is a 2.4.11 Focus Not Obscured failure. Reserve space with scroll-margin-top on the target so it stops below the fixed header:
#main-content {
/* Match this to the height of your sticky header */
scroll-margin-top: 5rem;
}

A related, more robust option is to point the skip link at the page’s <h1> rather than the <main> wrapper, giving the heading the tabindex="-1" and the scroll-margin-top. Landing on the heading means the screen reader announces the page title as focus arrives, which is a helpful confirmation of where the user now is.

The markup is the same in a single-page app, but client-side routing adds a problem the static case does not have. When the user navigates, the page does not reload, so keyboard focus stays wherever it was, often on a link inside the navigation, and the new view renders around that stale focus. The skip link still helps within a view, but you now also owe deliberate focus management on every route change.
In React, that is a small SkipLink component plus an effect that moves focus to the main region whenever the route changes:
function SkipLink() {
return (
<a className="skip-link" href="#main-content">
Skip to main content
</a>
)
}

// On each route change, move focus to the new view's main region
function useFocusMainOnRouteChange(pathname, mainRef) {
useEffect(() => {
mainRef.current?.focus()
}, [pathname, mainRef])
}

function Layout({ children }) {
const pathname = usePathname()
const mainRef = useRef(null)
useFocusMainOnRouteChange(pathname, mainRef)

return (
<>
<SkipLink />
<SiteHeader />
<main id="main-content" tabIndex={-1} ref={mainRef}>
{children}
</main>
</>
)
}

Svelte sets ARIA attributes with an ordinary curly-brace expression in markup, and it stringifies booleans for you — aria-expanded={isOpen} renders aria-expanded="true" or "false". The rule that trips teams up is what Svelte does with empty values: when an expression is null or undefined, Svelte omits the attribute entirely. In Svelte 5 you drive these from runes.
<script lang="ts">
let isOpen = $state(false)
let email = $state("")
// $derived recomputes whenever email changes
let hasError = $derived(email.length > 0 && !email.includes("@"))
</script>

<!-- Boolean state: renders aria-expanded="true" / "false" -->
<button aria-expanded={isOpen} aria-controls="panel" on:click={() => (isOpen = !isOpen)}>
Menu
</button>

<!-- Conditional attribute: present only when there is an error,
omitted entirely when the expression is undefined -->
<input
aria-invalid={hasError || undefined}
aria-describedby={hasError ? "email-error" : undefined}
/>

<!-- Token attributes: bind the token, not a bare boolean -->
<a aria-current={isActive ? "page" : undefined} {href}>Home</a>

A Svelte action is a function you attach to an element with use:name. Svelte calls it with the real DOM node when the element mounts and runs the destroy() you return when it unmounts. That lifecycle makes actions the idiomatic Svelte home for accessibility behavior that needs a live element — a focus trap, click-outside-to-close, or moving focus on open. You write the logic once and reuse it with a single attribute.
// actions/trapFocus.ts — a reusable focus trap
export function trapFocus(node: HTMLElement) {
const previouslyFocused = document.activeElement as HTMLElement | null

const selector =
'a[href], button:not([disabled]), input:not([disabled]), ' +
'select, textarea, [tabindex]:not([tabindex="-1"])'
const focusable = () =>
Array.from(node.querySelectorAll<HTMLElement>(selector))

// Move focus into the dialog when it opens
focusable()[0]?.focus()

function onKeydown(e: KeyboardEvent) {
if (e.key !== "Tab") return
const items = focusable()
const first = items[0]
const last = items[items.length - 1]
if (e.shiftKey && document.activeElement === first) {
last.focus()
e.preventDefault()
} else if (!e.shiftKey && document.activeElement === last) {
first.focus()
e.preventDefault()
}
}

node.addEventListener("keydown", onKeydown)

return {
destroy() {
node.removeEventListener("keydown", onKeydown)
previouslyFocused?.focus() // restore focus to what opened the dialog
},
}
}

Reactivity updates the DOM silently. When search results load, a toast appears, or a form saves, a sighted user sees it instantly — a screen reader user hears nothing unless the change happens inside an aria-live region. The catch is the same one every framework hits: a screen reader only announces a live region that already existed in the DOM before its content changed. Mount that region with {#if} at the moment the message appears and nothing is announced.
<!-- Broken: the region is created at the same moment as its text,
so the browser treats it as initial content, not an update -->
{#if message}
<p aria-live="polite">{message}</p>
{/if}

<!-- Correct: the region is always in the DOM; only its text changes -->
<p aria-live="polite" class="sr-only">{message}</p>
// lib/announcer.svelte.ts — one persistent region for the whole app
export const announcer = $state({ message: "" })

export function announce(text: string) {
announcer.message = "" // reset so identical messages re-announce
requestAnimationFrame(() => {
announcer.message = text
})
}

bind:value handles the data binding, but says nothing about accessibility. Associate every input with a <label> (the compiler's a11y_label_has_associated_control warning enforces this), then link the error message with aria-describedby and mark the field with aria-invalid — binding undefined so the attributes disappear when the field is valid.
<script lang="ts">
let email = $state("")
let touched = $state(false)
let invalid = $derived(touched && !/^[^@]+@[^@]+\.[^@]+$/.test(email))
</script>

<form on:submit|preventDefault={submit}>
<label for="email">Email</label>
<input
id="email"
type="email"
bind:value={email}
on:blur={() => (touched = true)}
aria-invalid={invalid || undefined}
aria-describedby={invalid ? "email-error" : undefined}
/>
{#if invalid}
<p id="email-error" class="error">Enter a valid email address.</p>
{/if}

<button type="submit">Create account</button>
</form>

Automated checks catch a meaningful share of issues and stop regressions — but they find roughly a third to a half of WCAG problems, so they supplement rather than replace manual testing. Svelte gives you an extra automated layer for free in the compiler; layer these into your workflow:
# 1. The compiler + svelte-check — a11y warnings fail the build
svelte-check --fail-on-warnings

# 2. Lint on top of the compiler — eslint-plugin-svelte
# In eslint.config.js, extend the svelte recommended config.
// 3. Component tests: @testing-library/svelte + vitest-axe
import { render } from "@testing-library/svelte"
import { axe } from "vitest-axe"
import TextField from "./TextField.svelte"

it("TextField has no axe violations", async () => {
const { container } = render(TextField, { props: { label: "Email", id: "email" } })
expect(await axe(container)).toHaveNoViolations()
})

// 4. End-to-end: axe-core in Playwright against real routes
import AxeBuilder from "@axe-core/playwright"

test("home page is accessible", async ({ page }) => {
await page.goto("/")
const results = await new AxeBuilder({ page }).analyze()
expect(results.violations).toEqual([])
})

A scrim is a semi-transparent layer between the image and the text. It darkens (or lightens) every pixel by the same proportion, which pulls the brightest highlights down to a level the text can beat.
.hero {
position: relative;
isolation: isolate;
display: grid;
align-items: end;
min-height: 28rem;
background-color: #1d2733; /* fallback, see fix 6 */
color: #fff;
}

.hero__img {
position: absolute;
inset: 0;
width: 100%;
height: 100%;
object-fit: cover;
z-index: -2;
}

/* The scrim */
.hero::before {
content: "";
position: absolute;
inset: 0;
z-index: -1;
background-color: rgb(0 0 0 / 0.55);
}

.hero__text {
padding: 2rem;
}

How to choose the opacity. There are two numbers worth knowing. The first is the smallest opacity that passes for your actual image, which the checker works out from a screenshot. The second is a ceiling that passes for any image. With pure white text, the worst possible pixel is pure white, so if the overlay is strong enough to make white text readable on white, it is strong enough for everything. These are the ceilings, worked out with the WCAG formula:

Overlay opacity that guarantees each contrast ratio over any image, for white and black text
Text and overlay 3:1 (large text) 4.5:1 (normal text) 7:1 (AAA)
White text (#fff), black overlay 42% 54% 66%
Black text (#000), white overlay 36% 46% 59%

So a 54% black overlay under white text passes 4.5:1 whatever photo an editor drops in later: pure white becomes about #757575, which is 4.6:1. Add a few points of margin for rounding, which is why the example uses 55%. The ceilings assume the overlay covers every pixel behind the text and that the text is pure white or pure black. Off-white text, a brand-tinted overlay or semi-transparent text all need measuring.
A gradient scrim keeps the rest of the photo bright by darkening only where the text sits. The common mistake is sizing the gradient as a percentage of the whole hero: on a phone the text wraps onto more lines and climbs into the faded part. Put the gradient on the text block instead, solid behind the text and fading only in the top padding:
.hero__text {
padding: 4rem 2rem 2rem;
/* 60% black behind every line of text,
fading out only in the top 4rem of padding */
background-image: linear-gradient(
to top,
rgb(0 0 0 / 0.6) calc(100% - 4rem),
rgb(0 0 0 / 0)
);
}

A panel behind the text takes the image out of the equation. An opaque panel is a flat colour you can check with any contrast checker, it survives every crop, and the rest of the photo stays untouched. A semi-opaque panel follows the same opacity ceilings as an overlay. For a headline that wraps, a highlight that follows each line looks lighter than a box.
.hero__panel {
max-width: 36rem;
padding: 1.25rem 1.5rem;
background-color: rgb(15 23 42 / 0.88);
color: #fff;
border-radius: 0.5rem;
}

/* A highlight that follows each line of a wrapped headline */
.hero__title span {
background-color: #0f172a;
color: #fff;
padding: 0.1em 0.35em;
-webkit-box-decoration-break: clone;
box-decoration-break: clone;
}

The Understanding document for 1.4.3 treats a wide border or halo around the letters as their background, while a thin outline counts as part of the letter. So a dark halo that fully surrounds every stroke can supply the contrast the image cannot. The usual decorative drop shadow does not: it is offset to one side, so one edge of every letter still touches the photo, and its blur fades to almost nothing a pixel or two out.
/* Not enough: offset, soft and faint */
.hero__title {
text-shadow: 2px 2px 4px rgb(0 0 0 / 0.4);
}

/* A halo: stacked shadows that surround every stroke */
.hero__title {
color: #fff;
text-shadow:
0 0 2px #000,
0 0 4px #000,
0 0 8px #000,
0 0 12px rgb(0 0 0 / 0.8);
}

A halo can be enough for a large, bold headline over a moderately busy image, once you have measured a screenshot of it. It is not enough for body copy or small text, where a halo muddies the letter shapes, or over very bright, detailed images. And it disappears completely in Windows contrast themes, which remove text shadows (fix 7 covers what happens instead). Use it as a finishing touch, not your only defence.

The cheapest fix is composition. Choose images with a large, even area (sky, wall, water, shadow) and keep that area behind the text with object-position. When one crop cannot serve every width, art-direct a different image for small screens, or stop overlapping altogether and stack the text under the photo.
/* Keep the calm water behind the text */
.hero__img {
object-position: 30% 50%;
}

@media (max-width: 40rem) {
.hero__img {
object-position: 60% 20%;
}
}

/* Or stop overlapping on small screens:
the text sits on the fallback colour below the photo */
@media (max-width: 40rem) {
.hero { display: block; }
.hero__img { position: static; height: 14rem; }
.hero::before { display: none; }
}

<picture>
<source media="(max-width: 40rem)" srcset="harbour-tall.jpg">
<img class="hero__img" src="harbour-wide.jpg" alt="">
</picture>

The most dependable version of this is editing the image file itself: export it darker, or pull down the highlights in the area behind the text. That costs nothing at runtime and looks the same everywhere. In CSS, a brightness() filter darkens the whole image, and a backdrop-filter blur on the text panel calms busy texture. Blur on its own is not a contrast fix, though: a blurred white cloud is still white. Pair it with a tint and measure the result.
.hero__img {
filter: brightness(0.6);
}

.hero__panel {
background-color: rgb(0 0 0 / 0.55);
-webkit-backdrop-filter: blur(12px);
backdrop-filter: blur(12px);
}

Images do not always load: slow connections, data savers, blocked requests, CDN outages, and the moment before a lazy-loaded image arrives all leave the text on whatever is behind the image. White text over a missing image usually ends up on white. W3C failure F24 warns against setting a text colour without a background colour, and notes that you should think about contrast for when the image is not displayed. Give the element behind the image a solid colour that passes with the text on its own: in the hero above, #1d2733 gives white text 15.1:1. With a CSS background image, put the colour in the same shorthand.
.banner {
/* The colour shows until, or instead of, the image */
background: #1d2733 url("harbour.jpg") center / cover no-repeat;
color: #fff;
}

In forced colours mode, which Windows contrast themes switch on, the browser replaces your colours with the user's and, as MDN's forced-colors reference describes, removes text-shadow and box-shadow and drops background images that are not loaded with url(). So a gradient scrim vanishes while the photo stays. To keep text readable, browsers paint a solid backplate behind it. Two rules follow: never set forced-color-adjust: none on hero text, which switches the backplate off, and if you want a guaranteed panel, give the text block system colours.
prefers-contrast: more matches when someone has asked their system for more contrast, such as Increase contrast on macOS. It is a cheap moment to strengthen the overlay or switch to a solid panel.
@media (prefers-contrast: more) {
.hero::before {
background-color: rgb(0 0 0 / 0.75);
}
.hero__panel {
background-color: #0f172a;
}
}

@media (forced-colors: active) {
.hero__text {
background-color: Canvas;
color: CanvasText;
}
}

A role overrides every native semantic on the element
This is the sharpest edge of ARIA. When you add a role, the element’s built-in meaning is replaced, not supplemented. <a href role="button"> stops being announced as a link. <ul role="menu"> is no longer a list, and its <li> children stop being list items. <table role="presentation"> loses all of its rows-and-cells meaning. That is sometimes exactly what you want, but it means a careless role silently strips real semantics, so add one only when you intend to change what the element is.

Here is a state kept in sync, the way rule three of section 2 demands. The visual change and the ARIA change happen together, in one place:
<button type="button" aria-expanded="false" aria-controls="panel">
Details
</button>
<div id="panel" hidden>...</div>

<script>
const btn = document.querySelector('button[aria-controls="panel"]');
const panel = document.getElementById('panel');
btn.addEventListener('click', () => {
const open = btn.getAttribute('aria-expanded') === 'true';
// Flip the visual state and the ARIA state in the same step
btn.setAttribute('aria-expanded', String(!open));
panel.hidden = open;
});
</script>

When something updates on the page without a full navigation, a saved confirmation, a validation error, a search-result count, a screen reader will not notice unless you tell it to. Live regions are how ARIA announces these changes politely, without stealing focus. This is the mechanism behind 4.1.3 Status Messages.
aria-live="polite" (or role="status") waits for the screen reader to finish what it is saying, then announces the change. This is the default choice for almost everything.
aria-live="assertive" (or role="alert") interrupts immediately. Reserve it for genuinely urgent, time-sensitive messages such as a submission error, and use it sparingly.
role="log" is a polite region for content that appends over time, such as a chat transcript.

The single most important implementation detail: the live region must already be in the DOM before you change its text. If you insert the region and its message at the same time, most screen readers treat it as initial content and stay silent. Render an empty region on load, then write into it.
<!-- Mounted empty on load; you set textContent later -->
<div id="status" role="status" aria-live="polite" class="sr-only"></div>

<script>
function announce(message) {
document.getElementById('status').textContent = message;
}
// announce('Settings saved.');
</script>

A dialog is the classic Vue focus challenge. When it opens, focus must move into it; while open, focus must stay trapped inside; on close, focus must return to the control that opened it. Vue's <Teleport> moves the dialog markup to <body> so it escapes any overflow or stacking context, and a focus-trap library keeps keyboard focus inside while it is open.
<script setup lang="ts">
import { ref, watch, nextTick } from "vue"
import { useFocusTrap } from "@vueuse/integrations/useFocusTrap"

const open = ref(false)
const dialog = ref<HTMLElement | null>(null)
const opener = ref<HTMLElement | null>(null)
const { activate, deactivate } = useFocusTrap(dialog)

watch(open, async (isOpen) => {
if (isOpen) {
opener.value = document.activeElement as HTMLElement
await nextTick()
activate() // move + trap focus inside the dialog
} else {
deactivate()
opener.value?.focus() // restore focus to what opened it
}
})
</script>

<template>
<button type="button" @click="open = true">Delete project</button>

<Teleport to="body">
<div v-if="open" class="backdrop" @click="open = false" />
<div
v-if="open"
ref="dialog"
role="dialog"
aria-modal="true"
aria-labelledby="dialog-title"
@keydown.esc="open = false"
>
<h2 id="dialog-title">Delete this project?</h2>
<p>This action cannot be undone.</p>
<button type="button" @click="open = false">Cancel</button>

Reactivity updates the DOM silently. When search results load, a toast appears, or a form saves, a sighted user sees it instantly — a screen reader user hears nothing unless the change happens inside an aria-live region. The Vue-specific catch: a screen reader only announces a live region that already existed in the DOM before its content changed. Mount that region with v-if at the moment the message appears and nothing is announced.
<!-- Broken: the region is created at the same moment as its text,
so the browser treats it as initial content, not an update -->
<p v-if="message" aria-live="polite">{{ message }}</p>

<!-- Correct: the region is always in the DOM; only its text changes -->
<p aria-live="polite" class="sr-only">{{ message }}</p>
// A reusable announcer composable — one persistent region for the app
// composables/useAnnouncer.ts
import { ref } from "vue"

const message = ref("")
export function useAnnouncer() {
function announce(text: string) {
message.value = "" // reset so identical messages re-announce
requestAnimationFrame(() => { message.value = text })
}
return { message, announce }
}

